      const discipline=r.list_id===288?(r.param==='M'?'raw:HS':'raw:DS'):(r.param==='M'?'raw:HD':'raw:DD');
      const older=h.prepare('SELECT * FROM ranking_snapshots WHERE nembadminton_member_id=? AND discipline=? AND version_date BETWEEN ? AND ? ORDER BY version_date DESC').all(link.nembadminton_member_id,discipline,'2025-07-01','2026-06-30').find(q=>calendar.includes(q.version_date)&&Math.abs(q.points-r.points)>=20);
